def circular_house_profit(nums):
    if len(nums) == 1:
        return nums[0]
    def rob(start, stop):
        previous, current = 0, 0
        for i in range(start, stop):
            previous, current = current, max(current, previous + nums[i])
        return current
    return max(rob(0, len(nums) - 1), rob(1, len(nums)))

